import{_ as a,o,c as t,a2 as r}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"Interface: PlayerMotion","description":"","frontmatter":{},"headers":[],"relativePath":"api/spool/interfaces/PlayerMotion.md","filePath":"api/spool/interfaces/PlayerMotion.md"}'),l={name:"api/spool/interfaces/PlayerMotion.md"};function c(n,e,i,s,d,h){return o(),t("div",null,[...e[0]||(e[0]=[r('<p><a href="./../">spool</a> / PlayerMotion</p><h1 id="interface-playermotion" tabindex="-1">Interface: PlayerMotion <a class="header-anchor" href="#interface-playermotion" aria-label="Permalink to &quot;Interface: PlayerMotion&quot;">​</a></h1><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/a78f16732a0f0e6d726740450f2db14c5715acca/spool/src/plugins/player_motion/index.ts#L60" target="_blank" rel="noreferrer">plugins/player_motion/index.ts:60</a></p><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to &quot;Properties&quot;">​</a></h2><h3 id="launchglobalxyz" tabindex="-1">launchGlobalXyz <a class="header-anchor" href="#launchglobalxyz" aria-label="Permalink to &quot;launchGlobalXyz&quot;">​</a></h3><blockquote><p><code>readonly</code> <strong>launchGlobalXyz</strong>: <code>FunctionRef</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/a78f16732a0f0e6d726740450f2db14c5715acca/spool/src/plugins/player_motion/index.ts#L105" target="_blank" rel="noreferrer">plugins/player_motion/index.ts:105</a></p><p><code>api/launch_global_xyz</code> - the raw function, to <code>ctx.call</code> yourself after setting <a href="#launchinput">launchInput</a>.</p><hr><h3 id="launchinput" tabindex="-1">launchInput <a class="header-anchor" href="#launchinput" aria-label="Permalink to &quot;launchInput&quot;">​</a></h3><blockquote><p><code>readonly</code> <strong>launchInput</strong>: <code>object</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/a78f16732a0f0e6d726740450f2db14c5715acca/spool/src/plugins/player_motion/index.ts#L111" target="_blank" rel="noreferrer">plugins/player_motion/index.ts:111</a></p><p>The <code>$x/$y/$z player_motion.api.launch</code> input scores, as typed <code>Score</code>s. These are <strong>fixed-point</strong>: <code>10000</code> == 1.0 block/tick. Prefer <a href="#launchlocal">launchLocal</a> / <a href="#launchglobal">launchGlobal</a>, which take plain block/tick floats and convert for you.</p><h4 id="x" tabindex="-1">x <a class="header-anchor" href="#x" aria-label="Permalink to &quot;x&quot;">​</a></h4><blockquote><p><code>readonly</code> <strong>x</strong>: <code>Score</code></p></blockquote><h4 id="y" tabindex="-1">y <a class="header-anchor" href="#y" aria-label="Permalink to &quot;y&quot;">​</a></h4><blockquote><p><code>readonly</code> <strong>y</strong>: <code>Score</code></p></blockquote><h4 id="z" tabindex="-1">z <a class="header-anchor" href="#z" aria-label="Permalink to &quot;z&quot;">​</a></h4><blockquote><p><code>readonly</code> <strong>z</strong>: <code>Score</code></p></blockquote><hr><h3 id="launchlocalxyz" tabindex="-1">launchLocalXyz <a class="header-anchor" href="#launchlocalxyz" aria-label="Permalink to &quot;launchLocalXyz&quot;">​</a></h3><blockquote><p><code>readonly</code> <strong>launchLocalXyz</strong>: <code>FunctionRef</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/a78f16732a0f0e6d726740450f2db14c5715acca/spool/src/plugins/player_motion/index.ts#L103" target="_blank" rel="noreferrer">plugins/player_motion/index.ts:103</a></p><p><code>api/launch_local_xyz</code> - the raw function, to <code>ctx.call</code> yourself after setting <a href="#launchinput">launchInput</a>.</p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to &quot;Methods&quot;">​</a></h2><h3 id="applyglobal" tabindex="-1">applyGlobal() <a class="header-anchor" href="#applyglobal" aria-label="Permalink to &quot;applyGlobal()&quot;">​</a></h3><blockquote><p><strong>applyGlobal</strong>(<code>ctx</code>, <code>velocity?</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/a78f16732a0f0e6d726740450f2db14c5715acca/spool/src/plugins/player_motion/index.ts#L99" target="_blank" rel="noreferrer">plugins/player_motion/index.ts:99</a></p><p>Like <a href="#launchglobal">launchGlobal</a>, but a <strong>sustained per-tick</strong> impulse along world axes - the natural fit for swing/grapple physics, where each tick you recompute a world-space velocity (e.g. toward an anchor) and re-apply it. See <a href="#applylocal">applyLocal</a> for the swap-free trigger model, the standstill caveat, and the no-velocity (runtime <a href="#launchinput">launchInput</a>) form.</p><p>Note: a velocity past the +/-12398 large-vector limit <code>return fail</code>s before the sustain flag is cleared, so it can leak into the next launch - a non-issue for per-tick velocities (a few blocks/tick), which is the only place this is used.</p><h4 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="ctx" tabindex="-1">ctx <a class="header-anchor" href="#ctx" aria-label="Permalink to &quot;ctx&quot;">​</a></h5><p><code>FunctionContext</code></p><h5 id="velocity" tabindex="-1">velocity? <a class="header-anchor" href="#velocity" aria-label="Permalink to &quot;velocity?&quot;">​</a></h5><p><code>GlobalVelocity</code></p><h4 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>void</code></p><hr><h3 id="applylocal" tabindex="-1">applyLocal() <a class="header-anchor" href="#applylocal" aria-label="Permalink to &quot;applyLocal()&quot;">​</a></h3><blockquote><p><strong>applyLocal</strong>(<code>ctx</code>, <code>velocity?</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/a78f16732a0f0e6d726740450f2db14c5715acca/spool/src/plugins/player_motion/index.ts#L87" target="_blank" rel="noreferrer">plugins/player_motion/index.ts:87</a></p><p>Like <a href="#launchlocal">launchLocal</a>, but a <strong>sustained per-tick</strong> impulse: it skips the gamemode-swap trigger and relies on the player <em>already moving</em> to fire the enchantment that tick. Call it every tick (<code>execute as @a[tag=…] at @s run …</code>) to drive continuous motion - a thrust, a grapple, the arc of a swing. The very first kick from a standstill still needs <a href="#launchlocal">launchLocal</a> (which forces the trigger); use this to maintain motion once underway.</p><p>Omit <code>velocity</code> to sustain whatever is already in <a href="#launchinput">launchInput</a> - the way to drive a <strong>runtime-computed</strong> vector (set the input scores yourself, then call this with no velocity).</p><h4 id="parameters-1" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-1" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="ctx-1" tabindex="-1">ctx <a class="header-anchor" href="#ctx-1" aria-label="Permalink to &quot;ctx&quot;">​</a></h5><p><code>FunctionContext</code></p><h5 id="velocity-1" tabindex="-1">velocity? <a class="header-anchor" href="#velocity-1" aria-label="Permalink to &quot;velocity?&quot;">​</a></h5><p><code>LocalVelocity</code></p><h4 id="returns-1" tabindex="-1">Returns <a class="header-anchor" href="#returns-1" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>void</code></p><hr><h3 id="launchglobal" tabindex="-1">launchGlobal() <a class="header-anchor" href="#launchglobal" aria-label="Permalink to &quot;launchGlobal()&quot;">​</a></h3><blockquote><p><strong>launchGlobal</strong>(<code>ctx</code>, <code>velocity</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/a78f16732a0f0e6d726740450f2db14c5715acca/spool/src/plugins/player_motion/index.ts#L73" target="_blank" rel="noreferrer">plugins/player_motion/index.ts:73</a></p><p>Launch the executing player by <code>velocity</code> <strong>along world axes</strong> (x/y/z in blocks/tick). Must run <code>at</code> the player. Inputs outside +/-12398 blocks/tick per axis hit the unsupported large-vector path and <code>return fail</code>.</p><h4 id="parameters-2" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-2" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="ctx-2" tabindex="-1">ctx <a class="header-anchor" href="#ctx-2" aria-label="Permalink to &quot;ctx&quot;">​</a></h5><p><code>FunctionContext</code></p><h5 id="velocity-2" tabindex="-1">velocity <a class="header-anchor" href="#velocity-2" aria-label="Permalink to &quot;velocity&quot;">​</a></h5><p><code>GlobalVelocity</code></p><h4 id="returns-2" tabindex="-1">Returns <a class="header-anchor" href="#returns-2" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>void</code></p><hr><h3 id="launchlocal" tabindex="-1">launchLocal() <a class="header-anchor" href="#launchlocal" aria-label="Permalink to &quot;launchLocal()&quot;">​</a></h3><blockquote><p><strong>launchLocal</strong>(<code>ctx</code>, <code>velocity</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/a78f16732a0f0e6d726740450f2db14c5715acca/spool/src/plugins/player_motion/index.ts#L67" target="_blank" rel="noreferrer">plugins/player_motion/index.ts:67</a></p><p>Launch the executing player by <code>velocity</code> <strong>relative to their facing</strong> (sideways/up/forward in blocks/tick). Emits the input writes + the call, so one line replaces the set-three-scores-then-call dance. Must run positioned as the player (e.g. <code>execute as @p at @s run ...</code>).</p><h4 id="parameters-3" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-3" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="ctx-3" tabindex="-1">ctx <a class="header-anchor" href="#ctx-3" aria-label="Permalink to &quot;ctx&quot;">​</a></h5><p><code>FunctionContext</code></p><h5 id="velocity-3" tabindex="-1">velocity <a class="header-anchor" href="#velocity-3" aria-label="Permalink to &quot;velocity&quot;">​</a></h5><p><code>LocalVelocity</code></p><h4 id="returns-3" tabindex="-1">Returns <a class="header-anchor" href="#returns-3" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>void</code></p>',74)])])}const b=a(l,[["render",c]]);export{u as __pageData,b as default};
